/**
 * Progressive-enhancement controller for the optional Pagefind SearchDialog.
 *
 * - Framework-free; no runtime npm dependency. The Pagefind browser bundle is
 *   generated by `npm run search:index` and loaded lazily as a runtime URL on the
 *   first eligible interaction, never on initial page load.
 * - Indexed text reaches the DOM only through textContent and created <mark>
 *   elements. Excerpt HTML from the index is never assigned to innerHTML.
 * - Every listener, timer, pending query and open modal is owned by an
 *   AbortController and released on ClientRouter swaps or DOM removal.
 */
import { announce } from './announce.ts';

export interface SearchCapability {
  readonly engine: 'pagefind';
  readonly bundlePath: string;
}

export interface SearchLabels {
  trigger: string;
  title: string;
  inputLabel: string;
  placeholder: string;
  close: string;
  idle: string;
  loading: string;
  empty: string;
  /** Plural categories from Intl.PluralRules; `other` is required. `{count}` and `{query}` are replaced. */
  results: Partial<Record<Intl.LDMLPluralRule, string>> & { other: string };
  unavailable: string;
  error: string;
}

export const DEFAULT_SEARCH_LABELS: Readonly<SearchLabels> = Object.freeze({
  trigger: 'Search',
  title: 'Search this site',
  inputLabel: 'Search terms',
  placeholder: '',
  close: 'Close',
  idle: 'Type at least two characters to search.',
  loading: 'Searching…',
  empty: 'No results for “{query}”.',
  results: { one: '1 result for “{query}”.', other: '{count} results for “{query}”.' },
  unavailable: 'Search is not available yet: this site’s search index has not been built.',
  error: 'Search failed. Please try again.',
});

export function resolveSearchLabels(overrides?: Partial<SearchLabels>): SearchLabels {
  return {
    ...DEFAULT_SEARCH_LABELS,
    ...overrides,
    results: { ...DEFAULT_SEARCH_LABELS.results, ...overrides?.results },
  } as SearchLabels;
}

/**
 * Derives the public directory URL of the Pagefind bundle from Baseline's
 * public capabilities. Returns null when search is not configured.
 * Configuration is not proof that an index exists; the browser reports a
 * missing index separately.
 */
export function resolveSearchBundleUrl(capabilities: { base: string; search: false | SearchCapability }): string | null {
  const search = capabilities.search;
  if (!search || search.engine !== 'pagefind') return null;
  const bundlePath = search.bundlePath.replace(/^\/+|\/+$/g, '');
  if (!bundlePath || /^[a-z][a-z0-9+.-]*:|(^|\/)\.\.(\/|$)|\\/i.test(bundlePath)) {
    throw new Error(`Invalid search bundlePath "${search.bundlePath}"`);
  }
  const base = (capabilities.base || '/').replace(/\/+$/, '');
  return `${base}/${bundlePath}/`;
}

export function formatSearchMessage(template: string, values: { count?: number; query?: string } = {}): string {
  return template
    .replaceAll('{count}', values.count === undefined ? '' : String(values.count))
    .replaceAll('{query}', values.query ?? '');
}

export function formatResultCount(labels: SearchLabels, count: number, query: string, lang?: string): string {
  let category: Intl.LDMLPluralRule = 'other';
  try {
    category = new Intl.PluralRules(lang || undefined).select(count);
  } catch {
    // Invalid or unsupported language tag: fall back to `other`.
  }
  const template = labels.results[category] ?? labels.results.other;
  return formatSearchMessage(template, { count, query });
}

/** True for form controls and editing hosts where a typed key belongs to the user. */
export function isEditableTarget(target: unknown): boolean {
  if (!target || typeof target !== 'object') return false;
  const element = target as {
    tagName?: string;
    type?: string;
    isContentEditable?: boolean;
    closest?: (selector: string) => unknown;
  };
  const tag = (element.tagName || '').toUpperCase();
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    const type = (element.type || 'text').toLowerCase();
    return !['button', 'submit', 'reset', 'checkbox', 'radio', 'range', 'color', 'file', 'image', 'hidden'].includes(type);
  }
  if (element.isContentEditable) return true;
  if (typeof element.closest === 'function' && element.closest('[contenteditable]:not([contenteditable="false"])')) return true;
  return false;
}

export interface ShortcutEventLike {
  key: string;
  ctrlKey: boolean;
  metaKey: boolean;
  altKey: boolean;
  shiftKey: boolean;
  defaultPrevented: boolean;
  isComposing?: boolean;
  keyCode?: number;
  repeat?: boolean;
  target: unknown;
}

/**
 * Classifies a keydown as a search shortcut. Ctrl+K / Cmd+K always qualify;
 * `/` only when enabled. Already-handled events, IME composition and keys
 * typed into editable elements are never claimed.
 */
export function matchSearchShortcut(event: ShortcutEventLike, options: { slash?: boolean } = {}): 'modifier' | 'slash' | null {
  if (event.defaultPrevented || event.isComposing || event.keyCode === 229 || event.repeat) return null;
  if (isEditableTarget(event.target)) return null;
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  if (key === 'k' && (event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey && !(event.ctrlKey && event.metaKey)) {
    return 'modifier';
  }
  if (options.slash && key === '/' && !event.ctrlKey && !event.metaKey && !event.altKey) return 'slash';
  return null;
}

export type ExcerptSegment = { text: string; mark: boolean };

const NAMED_ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };

export function decodeEntities(value: string): string {
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+|#39);/gi, (match, entity: string) => {
    const lower = entity.toLowerCase();
    if (lower.startsWith('#x') || lower.startsWith('#')) {
      const code = lower.startsWith('#x') ? parseInt(lower.slice(2), 16) : parseInt(lower.slice(1), 10);
      if (!Number.isFinite(code) || code < 0 || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return match;
      return String.fromCodePoint(code);
    }
    return NAMED_ENTITIES[lower] ?? match;
  });
}

/**
 * Converts a Pagefind excerpt (escaped text plus <mark> highlights) into inert
 * text segments. Any other markup is discarded rather than interpreted.
 */
export function parseExcerpt(excerpt: string): ExcerptSegment[] {
  const segments: ExcerptSegment[] = [];
  let mark = false;
  for (const part of String(excerpt ?? '').split(/(<\/?mark\b[^>]*>)/i)) {
    if (/^<mark\b/i.test(part)) { mark = true; continue; }
    if (/^<\/mark/i.test(part)) { mark = false; continue; }
    const text = decodeEntities(part.replace(/<[^>]*>?/g, ''));
    if (!text) continue;
    const last = segments[segments.length - 1];
    if (last && last.mark === mark) last.text += text;
    else segments.push({ text, mark });
  }
  return segments;
}

/** Accepts only same-origin http(s) result URLs; returns an absolute href or null. */
export function safeResultHref(url: unknown, pageHref: string): string | null {
  if (typeof url !== 'string' || !url.trim()) return null;
  try {
    const page = new URL(pageHref);
    const target = new URL(url, page);
    if (!['http:', 'https:'].includes(target.protocol) || target.origin !== page.origin || target.username || target.password) return null;
    return target.href;
  } catch {
    return null;
  }
}

/** True when a pointer position is beyond a box's edges. Exported for browser-free tests. */
export function isOutsideRect(
  point: { clientX: number; clientY: number },
  rect: { left: number; right: number; top: number; bottom: number },
): boolean {
  return point.clientX < rect.left || point.clientX > rect.right || point.clientY < rect.top || point.clientY > rect.bottom;
}

/* ------------------------------------------------------------------ */
/* Browser controller                                                  */
/* ------------------------------------------------------------------ */

interface PagefindResultData {
  url: string;
  excerpt?: string;
  meta?: Record<string, string>;
}

interface PagefindModule {
  init?: () => Promise<void> | void;
  options?: (options: Record<string, unknown>) => Promise<void> | void;
  search: (query: string) => Promise<{ results: Array<{ id: string; data: () => Promise<PagefindResultData> }> } | null>;
}

export type SearchState = 'idle' | 'loading' | 'results' | 'empty' | 'unavailable' | 'error';

const bundleCache = new Map<string, Promise<PagefindModule>>();

/** Imports the generated bundle as a runtime URL, outside Vite's module graph. */
function loadBundle(bundleUrl: string): Promise<PagefindModule> {
  const href = new URL('pagefind.js', new URL(bundleUrl, document.baseURI)).href;
  let pending = bundleCache.get(href);
  if (!pending) {
    pending = (async () => {
      const module = (await import(/* @vite-ignore */ href)) as PagefindModule;
      if (!module || typeof module.search !== 'function') throw new Error('Pagefind bundle has no search()');
      await module.options?.({ excerptLength: 24 });
      await module.init?.();
      return module;
    })();
    // A failed load may succeed after an index is built; do not cache failure.
    pending.catch(() => bundleCache.delete(href));
    bundleCache.set(href, pending);
  }
  return pending;
}

const MIN_QUERY_LENGTH = 2;
const liveControllers = new Set<SearchController>();
const activeControllers = new WeakMap<HTMLElement, SearchController>();

export class SearchController {
  readonly root: HTMLElement;
  private readonly lifetime = new AbortController();
  private query?: AbortController;
  private debounceTimer?: number;
  private invoker: HTMLElement | null = null;
  private readonly dialog: HTMLDialogElement | null;
  private readonly trigger: HTMLButtonElement | null;
  private readonly input: HTMLInputElement | null;
  private readonly status: HTMLElement | null;
  private readonly list: HTMLElement | null;
  private readonly labels: SearchLabels;
  private readonly bundleUrl: string;
  private readonly announcerId: string;
  private readonly maxResults: number;
  private readonly slash: boolean;
  state: SearchState = 'idle';

  constructor(root: HTMLElement) {
    this.root = root;
    this.dialog = root.querySelector('dialog[data-search-dialog]');
    this.trigger = root.querySelector('[data-search-trigger]');
    this.input = root.querySelector('[data-search-input]');
    this.status = root.querySelector('[data-search-status]');
    this.list = root.querySelector('[data-search-results]');
    this.bundleUrl = root.dataset.searchBundle || '';
    this.announcerId = root.dataset.announcerId || '';
    this.maxResults = Math.min(50, Math.max(1, Number(root.dataset.maxResults) || 8));
    this.slash = root.dataset.slashShortcut === 'true';
    let parsed: Partial<SearchLabels> | undefined;
    try { parsed = JSON.parse(root.dataset.labels || '{}'); } catch { parsed = undefined; }
    this.labels = resolveSearchLabels(parsed);
    liveControllers.add(this);
    this.init();
  }

  get isDestroyed(): boolean {
    return this.lifetime.signal.aborted;
  }

  get isOpen(): boolean {
    return Boolean(this.dialog?.open);
  }

  private init() {
    const { dialog, trigger, input } = this;
    if (!dialog || !trigger || !input || !this.bundleUrl || typeof dialog.showModal !== 'function') return;
    const signal = this.lifetime.signal;

    trigger.hidden = false;
    this.root.querySelectorAll<HTMLElement>('[data-search-fallback]').forEach((link) => { link.hidden = true; });
    this.root.setAttribute('data-search-enhanced', 'true');
    const hint = this.root.querySelector<HTMLElement>('.search__shortcut');
    if (hint && /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent)) hint.textContent = '⌘ K';

    trigger.addEventListener('click', () => this.open(trigger), { signal });
    this.root.querySelectorAll<HTMLElement>('[data-search-close]').forEach((button) =>
      button.addEventListener('click', () => this.close(), { signal }));
    // closedby="any" gives native light dismiss. Safari does not support it yet, so
    // compare press and release positions there: a text-selection drag that ends on
    // the backdrop must not dismiss, and event.target cannot distinguish that case.
    if (!('closedBy' in HTMLDialogElement.prototype)) {
      let pressedOutside = false;
      dialog.addEventListener('pointerdown', (event) => {
        pressedOutside = isOutsideRect(event, dialog.getBoundingClientRect());
      }, { signal });
      dialog.addEventListener('pointerup', (event) => {
        if (pressedOutside && isOutsideRect(event, dialog.getBoundingClientRect())) this.close();
      }, { signal });
    }
    dialog.addEventListener('close', () => this.onClosed(), { signal });
    // Chromium consumes Escape in a non-empty type="search" input to clear it,
    // so the native cancel never fires. Escape always dismisses the dialog here.
    dialog.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || event.isComposing || event.keyCode === 229 || event.defaultPrevented) return;
      event.preventDefault();
      this.close();
    }, { signal });
    input.addEventListener('input', () => this.schedule(), { signal });
    this.root.querySelector('form[data-search-form]')?.addEventListener('submit', (event) => {
      event.preventDefault();
      this.flush();
      this.list?.querySelector<HTMLAnchorElement>('a[href]')?.focus();
    }, { signal });

    document.addEventListener('keydown', (event) => {
      if (!this.ownsShortcuts()) return;
      if (this.isOpen && (event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k' && !event.defaultPrevented && !event.isComposing) {
        event.preventDefault();
        input.focus();
        input.select();
        return;
      }
      if (this.isOpen) return;
      if (!matchSearchShortcut(event, { slash: this.slash })) return;
      event.preventDefault();
      const focused = document.activeElement;
      this.open(focused instanceof HTMLElement && focused !== document.body ? focused : trigger);
    }, { signal });
  }

  /** Only the first connected, enhanced instance responds to global shortcuts. */
  private ownsShortcuts(): boolean {
    for (const controller of liveControllers) {
      if (!controller.isDestroyed && controller.root.isConnected && controller.root.hasAttribute('data-search-enhanced')) return controller === this;
    }
    return false;
  }

  open(invoker?: HTMLElement | null) {
    if (this.isDestroyed || !this.dialog || this.dialog.open) return;
    this.invoker = invoker ?? this.trigger;
    this.trigger?.setAttribute('aria-expanded', 'true');
    this.dialog.showModal();
    this.input?.focus();
    this.input?.select();
    if (this.state === 'idle') this.setStatus('idle', this.labels.idle);
    // Begin fetching the bundle on the first deliberate open, not on page load.
    loadBundle(this.bundleUrl).catch(() => {});
    if ((this.input?.value.trim().length ?? 0) >= MIN_QUERY_LENGTH) this.flush();
  }

  close() {
    if (this.dialog?.open) this.dialog.close();
  }

  private onClosed() {
    this.cancelPending();
    this.trigger?.setAttribute('aria-expanded', 'false');
    if (this.isDestroyed) return;
    const target = this.invoker?.isConnected ? this.invoker : this.trigger?.isConnected ? this.trigger : null;
    this.invoker = null;
    if (target && target !== document.activeElement) {
      try { target.focus({ preventScroll: true }); } catch { /* detached during close */ }
    }
  }

  private cancelPending() {
    if (this.debounceTimer !== undefined) {
      window.clearTimeout(this.debounceTimer);
      this.debounceTimer = undefined;
    }
    this.query?.abort();
    this.query = undefined;
    this.list?.removeAttribute('aria-busy');
  }

  private schedule() {
    if (this.debounceTimer !== undefined) window.clearTimeout(this.debounceTimer);
    this.debounceTimer = window.setTimeout(() => { this.debounceTimer = undefined; this.flush(); }, 120);
  }

  private flush() {
    if (this.debounceTimer !== undefined) {
      window.clearTimeout(this.debounceTimer);
      this.debounceTimer = undefined;
    }
    void this.run(this.input?.value ?? '');
  }

  /** Runs a query; any newer query or teardown supersedes it. */
  async run(raw: string): Promise<void> {
    this.query?.abort();
    const controller = new AbortController();
    this.query = controller;
    const { signal } = controller;
    const query = raw.trim();

    if (query.length < MIN_QUERY_LENGTH) {
      this.renderResults([]);
      this.setStatus('idle', this.labels.idle);
      this.list?.removeAttribute('aria-busy');
      return;
    }

    this.setStatus('loading', this.labels.loading);
    this.list?.setAttribute('aria-busy', 'true');
    let module: PagefindModule;
    try {
      module = await loadBundle(this.bundleUrl);
    } catch {
      if (signal.aborted || this.isDestroyed) return;
      this.list?.removeAttribute('aria-busy');
      this.renderResults([]);
      this.setStatus('unavailable', this.labels.unavailable, 'assertive');
      return;
    }

    try {
      const search = await module.search(query);
      if (signal.aborted || this.isDestroyed) return;
      const hits = search?.results ?? [];
      const data = await Promise.all(hits.slice(0, this.maxResults).map((hit) => hit.data()));
      if (signal.aborted || this.isDestroyed) return;
      this.list?.removeAttribute('aria-busy');
      const rendered = this.renderResults(data);
      if (rendered === 0) {
        this.setStatus('empty', formatSearchMessage(this.labels.empty, { query }), 'polite');
      } else {
        const lang = document.documentElement.lang;
        this.setStatus('results', formatResultCount(this.labels, hits.length, query, lang), 'polite');
      }
    } catch {
      if (signal.aborted || this.isDestroyed) return;
      this.list?.removeAttribute('aria-busy');
      this.renderResults([]);
      this.setStatus('error', this.labels.error, 'assertive');
    }
  }

  private setStatus(state: SearchState, message: string, priority?: 'polite' | 'assertive') {
    this.state = state;
    this.root.setAttribute('data-search-state', state);
    if (this.status) this.status.textContent = message;
    if (priority && this.announcerId) announce(this.announcerId, message, { priority, signal: this.query?.signal });
  }

  /** Renders results through textContent and created elements only. */
  private renderResults(results: PagefindResultData[]): number {
    const list = this.list;
    if (!list) return 0;
    list.replaceChildren();
    let count = 0;
    for (const result of results) {
      const href = safeResultHref(result?.url, location.href);
      if (!href) continue;
      const item = document.createElement('li');
      item.className = 'search__result';
      const link = document.createElement('a');
      link.className = 'search__result-link';
      link.href = href;
      const title = document.createElement('span');
      title.className = 'search__result-title';
      title.textContent = (result.meta?.title || '').trim() || new URL(href).pathname;
      link.append(title);
      const segments = parseExcerpt(result.excerpt || '');
      if (segments.length) {
        const excerpt = document.createElement('span');
        excerpt.className = 'search__result-excerpt';
        for (const segment of segments) {
          if (segment.mark) {
            const mark = document.createElement('mark');
            mark.textContent = segment.text;
            excerpt.append(mark);
          } else {
            excerpt.append(document.createTextNode(segment.text));
          }
        }
        link.append(excerpt);
      }
      link.addEventListener('click', () => { this.invoker = null; }, { signal: this.lifetime.signal });
      item.append(link);
      list.append(item);
      count += 1;
    }
    return count;
  }

  destroy() {
    if (this.isDestroyed) return;
    this.cancelPending();
    this.lifetime.abort();
    if (this.dialog?.open) {
      try { this.dialog.close(); } catch { /* already detached */ }
    }
    this.trigger?.setAttribute('aria-expanded', 'false');
    this.invoker = null;
    this.root.removeAttribute('data-search-enhanced');
    liveControllers.delete(this);
    activeControllers.delete(this.root);
  }
}

export function getSearchController(root: HTMLElement): SearchController | undefined {
  return activeControllers.get(root);
}

export function purgeDisconnectedSearch(): void {
  for (const controller of Array.from(liveControllers)) {
    if (!controller.root.isConnected) controller.destroy();
  }
}

/** Tears down every instance except persisted roots that survive into the next document. */
export function teardownSearch(newDocument?: Document): void {
  for (const controller of Array.from(liveControllers)) {
    const persistKey = controller.root.closest('[data-astro-transition-persist]')?.getAttribute('data-astro-transition-persist');
    const survives = Boolean(persistKey) && controller.root.isConnected &&
      Boolean(newDocument?.querySelector(`[data-astro-transition-persist="${CSS.escape(persistKey!)}"]`));
    if (survives) controller.close();
    else controller.destroy();
  }
}

export function initSearch(container: Document | HTMLElement = document): void {
  purgeDisconnectedSearch();
  container.querySelectorAll<HTMLElement>('[data-search-root]').forEach((root) => {
    const existing = activeControllers.get(root);
    if (existing && !existing.isDestroyed) return;
    activeControllers.set(root, new SearchController(root));
  });
}

let lifecycleBound = false;
let disconnectObserver: MutationObserver | null = null;

/** Binds ClientRouter lifecycle hooks once per document. Safe to call repeatedly. */
export function bindSearchLifecycle(): void {
  if (lifecycleBound || typeof document === 'undefined') return;
  lifecycleBound = true;
  document.addEventListener('astro:before-swap', (event) => {
    teardownSearch((event as unknown as { newDocument?: Document }).newDocument);
  });
  document.addEventListener('astro:page-load', () => initSearch());
  try {
    disconnectObserver = new MutationObserver(() => {
      for (const controller of liveControllers) {
        if (!controller.root.isConnected) { purgeDisconnectedSearch(); break; }
      }
    });
    disconnectObserver.observe(document.documentElement, { childList: true, subtree: true });
  } catch {
    // MutationObserver unavailable: ClientRouter hooks still own teardown.
  }
}
